<script setup>
import {computed,ref} from 'vue'
import Icon from './Icon.vue'
import {marketTiers,institutionalRates,minorAmount,revenueQuote,schoolQuote,legacyQuote,formatMoney} from './pricing'
const props=defineProps({member:Object})
defineEmits(['study','results','quizzes'])
const model=ref('share'),tier=ref('A'),gross=ref('500000'),currency=ref('LKR'),gateway=ref('0'),tax=ref('0'),refund=ref('0'),reverseFee=ref(true),students=ref(500),rate=ref('lk'),discount=ref(0),base=ref('15000')
const quote=computed(()=>{try{if(model.value==='share')return revenueQuote({gross:minorAmount(gross.value),rateBps:marketTiers.find(t=>t.id===tier.value).bps,gateway:minorAmount(gateway.value),tax:minorAmount(tax.value),refund:minorAmount(refund.value),reverseFee:reverseFee.value});if(model.value==='school')return schoolQuote({activeStudents:Number(students.value),unitMinor:institutionalRates.find(r=>r.id===rate.value).minor,discountBps:Number(discount.value)});return legacyQuote(Number(students.value),minorAmount(base.value))}catch(e){return {error:e.message}}})
const quoteCurrency=computed(()=>model.value==='share'?currency.value:model.value==='school'?institutionalRates.find(r=>r.id===rate.value).currency:'LKR')
const money=value=>formatMoney(value,quoteCurrency.value)
</script>
<template><div class="page-heading"><div><span class="eyebrow">ROOM TO GROW, AT YOUR OWN PACE</span><h1>Plans & little extras.</h1><p>{{member.role==='Student'?'Keep learning. Add a little comfort when it suits you.':'A clear commercial model for every kind of learning community.'}}</p></div><span class="badge violet">Pricing framework · preview</span></div>
<div v-if="member.role==='Student'" class="student-plan-grid"><section class="panel plan-card"><span class="badge green">Always available</span><h2>Study essentials</h2><strong>Free</strong><p>A focus timer, stopwatch, breaks, quiet garden wallpaper and dark theme. Your classes and published results keep their existing access rules.</p><button class="button subtle" @click="$emit('study')">Open Study Space <Icon name="ArrowRight" :size="16"/></button></section><section class="panel plan-card featured"><span class="badge violet">Optional monthly subscription</span><h2>Study Plus</h2><strong>Price to be configured</strong><p>Gentle music, rain sounds, premium wallpapers and a cute theme. Optional comfort for your study routine.</p><button class="button primary" @click="$emit('study')">Explore Study Plus <Icon name="Sparkles" :size="16"/></button><small>30-day demo access only. No payment or auto-renewal.</small></section><section class="panel plan-card"><span class="badge peach">Separate optional add-on</span><h2>GPA calculator</h2><strong>Price to be configured</strong><p>Explore credit-weighted what-if scenarios. Published grades remain available without buying the calculator.</p><button class="button subtle" @click="$emit('results')">View Results & GPA</button></section></div>
<template v-else><div class="provider-plan-grid"><section class="panel plan-card"><span class="badge violet">Teachers · academies · course creators</span><h2>Earn as you teach.</h2><p>A percentage of eligible collected class/course payments. Contract terms separate the platform fee, gateway fee, tax and refunds.</p><strong>2.5%–7%</strong><small>Commercial tiers, approved before activation.</small></section><section class="panel plan-card"><span class="badge mint">Schools · universities · enterprise</span><h2>A predictable campus bill.</h2><p>Fixed per-active-student monthly pricing, with approved volume discounts or an enterprise quote.</p><strong>LKR 100 / student</strong><small>Sri Lanka launch reference. International reference rates below.</small></section><section class="panel plan-card"><span class="badge peach">Optional teacher add-on</span><h2>AI Quiz</h2><p>Separately priced entitlement per teacher. Manual quizzes remain free; generation is simulated in this preview.</p><strong>Price to be configured</strong><button v-if="member.role==='Teacher'" class="button subtle" @click="$emit('quizzes')">Explore lesson quizzes</button></section></div>
<section class="panel pricing-calculator"><div class="section-heading"><div><h2>Make the numbers clear.</h2><p>Illustrative quotes from your two pricing documents. Nothing here changes an invoice or charges an account.</p></div><Icon name="Calculator" :size="28"/></div><div class="pricing-layout"><form @submit.prevent><label>Commercial model<select v-model="model"><option value="share">Revenue share · teachers and academies</option><option value="school">Per active student · institutions</option><option value="legacy">Legacy / custom · 500 included</option></select></label><template v-if="model==='share'"><div class="form-row"><label>Currency<select v-model="currency"><option>LKR</option><option>USD</option><option>AED</option><option>GBP</option></select></label><label>Commercial tier<select v-model="tier"><option v-for="t in marketTiers" :value="t.id">{{t.id}} · {{t.title}} · {{t.bps/100}}%</option></select></label></div><label>Gross collected payments<input v-model="gross" inputmode="decimal"></label><div class="form-row"><label>Gateway deduction<input v-model="gateway" inputmode="decimal"></label><label>Tax deduction<input v-model="tax" inputmode="decimal"></label></div><label>Refunded amount<input v-model="refund" inputmode="decimal"></label><label class="checkbox-label"><input type="checkbox" v-model="reverseFee">Reverse proportional platform fee on refund</label></template><template v-else><label>Distinct active students<input v-model.number="students" type="number" min="0" max="1000000" step="1"></label><template v-if="model==='school'"><label>Reference student rate<select v-model="rate"><option v-for="r in institutionalRates" :value="r.id">{{r.title}} · {{formatMoney(r.minor,r.currency)}} / month</option></select></label><label>Approved volume discount<select v-model.number="discount"><option :value="0">0% · no discount</option><option :value="1000">10%</option><option :value="2000">20%</option></select></label><p class="field-help">Up to 10% for 501–2,000; up to 20% for 2,001–10,000. Discounts need an approved quote. Above 10,000 requires enterprise review.</p></template><label v-else>Contract base fee · LKR<input v-model="base" inputmode="decimal"><small>LKR 15,000 is an example, not an approved price. The earlier plan adds LKR 50 for each active student above 500.</small></label></template></form><div class="pricing-summary" aria-live="polite"><p v-if="quote.error" class="error">{{quote.error}}</p><template v-else><span class="eyebrow">{{model==='share'?'COLLECTION BREAKDOWN':'ESTIMATED MONTHLY BILL'}}</span><template v-if="model==='share'"><dl><dt>Gross collected</dt><dd>{{money(quote.gross)}}</dd><dt>Refunds</dt><dd>− {{money(quote.refund)}}</dd><dt>Original platform fee</dt><dd>{{money(quote.originalFee)}}</dd><dt>Fee reversal</dt><dd>− {{money(quote.reversal)}}</dd><dt>Platform revenue after reversal</dt><dd>{{money(quote.platformFee)}}</dd><dt>Gateway deduction</dt><dd>− {{money(quote.gateway)}}</dd><dt>Tax deduction</dt><dd>− {{money(quote.tax)}}</dd></dl><small>Estimated provider balance</small><strong>{{money(quote.net)}}</strong><p v-if="quote.net<0" class="error">Deductions exceed proceeds. Review the contract and adjustments.</p></template><template v-else><strong>{{money(quote.total)}}</strong><p v-if="model==='school'">{{students}} active students · {{money(quote.discount)}} approved discount</p><p v-else>{{quote.extra}} students above the 500 included</p><span v-if="quote.requiresQuote" class="badge peach">Enterprise quote required</span></template><p class="field-help">Quote only. No currency conversion, gateway settlement, tax advice or automated payout. Figures depend on your agreed contract.</p></template></div></div></section><section class="panel pricing-process"><h2>One account. One clear billing agreement.</h2><div><p><b>01</b>Choose provider type and billing country.</p><p><b>02</b>Review the proposed tier or approved contract.</p><p><b>03</b>Snapshot fees when a verified payment settles.</p><p><b>04</b>Report gross, platform, gateway, tax, refunds and net separately.</p></div><p class="field-help">Market tiers are commercial settings, not permanent labels for countries. Starter, Growth and Professional packages need fixed subscription amounts and rate reductions before they can be sold. The existing 500-student plan remains a separate legacy/custom model; models must never be stacked without an explicit contract.</p></section></template></template>
