x){.student-plan-grid,.provider-plan-grid{grid-template-columns:1fr}.pricing-layout{gap:25px}.pricing-process>div{grid-template-columns:1fr 1fr}}@media(max-width:700px){.pricing-layout{grid-template-columns:1fr}.pricing-process>div{grid-template-columns:1fr}.pricing-summary{padding:22px}.pricing-summary dl{font-size:10px}.plan-card{padding:24px}}</style>
